import {createRoot}from'react-dom/client';import {useState}from'react';import {EntrySafety,useUnsavedEntry}from'../../apps/web/app/entry-safety';import GoogleNotice from'../../apps/web/app/google-connection-notice';import GoogleControls from'../../apps/web/app/google-controls';
function Screen(){const [dirty,setDirty]=useState(false);useUnsavedEntry('synthetic-draft',dirty);return <main className="shell"><label><input type="checkbox" checked={dirty} onChange={e=>setDirty(e.target.checked)}/>Synthetic unsaved draft</label>{new URLSearchParams(location.search).get('view')!=='notice'?<GoogleControls organization="20000000-0000-4000-8000-000000000001" timezone="America/Chicago" view="settings" compact={new URLSearchParams(location.search).get('view')==='compact'}/>:<GoogleNotice organization="20000000-0000-4000-8000-000000000001" onSetup={()=>{throw Error('Reconnect should not require opening setup')}}/>}</main>}
createRoot(document.getElementById('root')!).render(<EntrySafety><Screen/></EntrySafety>);
